INSERT INTO "public"."content" ("id", "section", "data", "updatedAt", "updatedBy") VALUES ('123f132a-cf26-4e4e-a461-0e0e3f773d44', 'footer', '{"email":"pokaz@hangarfilmowy.pl","phone":"+48 602 451 036","slogan":"Hangar Filmowy - Kino pod gwiazdami","address":"Polska (zasięg ogólnopolski)"}', '2025-12-31 10:26:35.355', 'pokaz@hangarfilmowy.pl'), ('44479851-aa66-41d2-ae63-825b71844aaa', 'offer', '{"cards":[{"title":"Technika Kinowa","imageUrl":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/be46b7f9-0db2-43a4-b1c8-f09d28395bd4.png","description":"Mobilne ekrany LED (nits), profesjonalne nagłośnienie i oświetlenie ambientowe."},{"title":"Licencje","imageUrl":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/2d4c9bdb-be33-490e-a77f-15eae702af66.png","description":"Zakup praw do publicznego odtwarzania."},{"title":"Strefa Widza","imageUrl":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/2193db9a-af2b-49e6-9aad-8981287b4bd9.png","description":"Wygodne leżaki i nastrojowe oświetlenie, tworzące magię kina letniego."},{"title":"Popcorn Bar","imageUrl":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/5599a0e6-f9e1-4823-a8db-51e7bc283d91.png","description":"Maszyny do popcornu, dystrybutory napojów i stoiska z przekąskami."}],"title":"po ostatnie ziarno kukurydzy.","subtitle":"Kompleksowa obsługa Twojego eventu.","titlePrefix":"Od licencji po"}', '2025-12-23 10:53:34.235', 'pokaz@hangarfilmowy.pl'), ('4fe48e45-6861-4653-85ff-34c72304df43', 'about', '{"title":"Wychodzimy z cienia.","content":"Przez lata kino plenerowe kojarzyło się z jednym: czekaniem na zmrok, walką z wiatrem falującym ekranem i kompromisami w jakości obrazu. Hangar Filmowy zmienia te zasady gry.\\n\\nJesteśmy zespołem pasjonatów kina i ekspertów od eventów. Nasza obietnica jest prosta: dostarczamy wrażenia kinowe (dosłownie!) w dowolnym miejscu w Polsce. Nie uznajemy półśrodków. Nasze ekrany świecą jasno, dźwięk wbija w fotel, a obsługa licencyjna zdejmuje Ci z głowy wszystkie formalności. Tworzymy wydarzenia, o których mieszkańcy rozmawiają miesiącami.\\n\\nWnosimy kino plenerowe na nowy poziom","imageUrl":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/e22e59d9-e184-486e-978e-23564a6442c7.png","paragraph1":"Przez lata kino plenerowe kojarzyło się z jednym: czekaniem na zmrok, walką z wiatrem falującym ekranem i kompromisami w jakości obrazu. Hangar Filmowy zmienia te zasady gry.","paragraph2":"Jesteśmy zespołem pasjonatów kina i ekspertów od eventów. Nasza obietnica jest prosta: dostarczamy wrażenia kinowe (dosłownie!) w dowolnym miejscu w Polsce. Nie uznajemy półśrodków. Nasze ekrany świecą jasno, dźwięk wbija w fotel, a obsługa licencyjna zdejmuje Ci z głowy wszystkie formalności. Tworzymy wydarzenia, o których mieszkańcy rozmawiają miesiącami.","titleGradient":"Wnosimy kino plenerowe na nowy poziom."}', '2025-12-23 10:48:10.254', 'pokaz@hangarfilmowy.pl'), ('8ca9496e-e949-4043-a2a6-b5c48484a1c1', 'for-who', '{"cards":[{"title":"Samorządy i Miasta","description":"Kino w parku, festiwal miejski, piknik rodzinny – zbuduj kapitał społeczny i pokaż, że Twoje miasto żyje kulturą."},{"title":"Hotele i Resorty","description":"Zaproponuj gościom wieczór filmowy w ogrodzie. Unikalne doświadczenie, które wyróżni Twoją ofertę i wygeneruje pozytywne recenzje."},{"title":"Firmy i Korporacje","description":"Integracja? Urodziny firmy? Prezentacja produktu? Zorganizuj kino na zamkniętym evencie – niezapomniane team-buildingowe doświadczenie."},{"title":"Festiwale i Eventy","description":"Festiwal muzyczny, food truck event, targi – dodaj kinową strefę, która przyciągnie tłumy i stworzy wiralowe momenty w social mediach."}],"title":"Tworzymy kino tam, gdzie go potrzebujesz"}', '2025-12-22 13:25:22.724', 'pokaz@hangarfilmowy.pl'), ('983bd592-b582-4bdf-ad77-cbd6b7fe684a', 'process', '{"steps":[{"title":"Ustalamy Termin i Wizję","description":"Dzwonisz/piszesz. Rozmawiamy o dacie, miejscu, rodzaju eventu i Twoich oczekiwaniach."},{"title":"Wybieramy Repertuar","description":"Podpowiadamy filmy dopasowane do grupy docelowej. Ty wybierasz – my załatwiamy licencje."},{"title":"Przygotowanie Przestrzeni","description":"Przyjeżdżamy z wyprzedzeniem, montujemy ekran, nagłośnienie, strefę widowni."},{"title":"Showtime!","description":"Twoi goście wchodzą, siadają, zapachy popcornu unoszą się w powietrzu – KINO się zaczyna!"}],"title":"Jak zorganizować kino?"}', '2025-12-23 08:15:48.05', 'pokaz@hangarfilmowy.pl'), ('9d317193-f274-4380-a9ff-b9e575e24072', 'why-us', '{"boxes":[{"title":"Obraz Żyleta","description":"Tradycyjna projekcja wymaga całkowitej ciemności. Nasze ekrany LED o ultrawysokiej jasności pozwalają rozpocząć seans wcześniej, nawet przy zachodzącym słońcu. Czerń jest czarna, kolory nasycone, a rozdzielczość zachwyca każdego widza."},{"title":"Odporność na Warunki","description":"Wiatr? Lekki deszcz? Dla naszych modułowych ścian LED to nie problem. Konstrukcja jest stabilna i bezpieczna, w przeciwieństwie do tradycyjnych ekranów pneumatycznych (\\"dmuchańców\\"), które poddają się przy mocniejszych podmuchach."},{"title":"Dźwięk, Który Czujesz","description":"Kino to w 50% dźwięk. Instalujemy profesjonalne systemy nagłośnieniowe, które zapewniają czystość dialogów i głębię efektów specjalnych, precyzyjnie pokrywając dźwiękiem strefę widowni."}],"title":"Dlaczego Ekran LED","subtitle":"Przesuń suwak, aby zobaczyć różnicę między tradycyjnym projektorem a naszą technologią LED.","comparisonImageUrl":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/b76cab8f-f023-40a5-9cf4-512ce30e726e.png"}', '2025-12-23 10:52:45.337', 'pokaz@hangarfilmowy.pl'), ('d1e2a9a7-4936-4a3a-a80a-6511a0ad4bf0', 'contact', '{"email":"pokaz@hangarfilmowy.pl","title":"Zaplanuj","subtitle":"Odpowiedz na kilka pytań, a my przygotujemy dla Ciebie ofertę szytą na miarę.","titleGradient":"Swoje Wydarzenie"}', '2025-12-23 08:25:29.22', 'pokaz@hangarfilmowy.pl'), ('ec745696-98e1-40a4-8515-863025772414', 'hero', '{"lead":"Ekrany LED o jasności 5000+ nits, widoczne nawet w pełnym słońcu. Bez pneumatycznych konstrukcji, które zdmuchuje wiatr. Kompleksowa obsługa: sprzęt, licencje, catering.","title":"Prawdziwe Kino","subtitle":"Wynajem profesjonalnego ekranu LED i organizacja kin plenerowych na terenie całej Polski.","ctaPrimary":"ZAPYTAJ O TERMIN","ctaSecondary":"ZOBACZ OFERTĘ","titleGradient":"Pod Gwiazdami","backgroundImage":"https://egzyaaeifdwpmmksqzeg.supabase.co/storage/v1/object/public/hangar-media/571ceffa-20f8-4ac6-8387-d057be4f1dde.png"}', '2025-12-23 10:44:35.884', 'pokaz@hangarfilmowy.pl');